		case (y_Q)
			A:	if (!w) Y_D = B;
				else Y_D = F;
			B:	if (!w) Y_D = C;
				else Y_D = F;
			C:	if (!w) Y_D = D;
				else Y_D = F;
			D:	if (!w) Y_D = E;
				else Y_D = F;
			E:	if (!w) Y_D = E;
				else Y_D = F;
			F:	if (!w) Y_D = B;
				else Y_D = G;
			G:	if (!w) Y_D = B;
				else Y_D = H;
			H:	if (!w) Y_D = B;
				else Y_D = I;
			I:	if (!w) Y_D = B;
				else Y_D = I;
			default: Y_D = 4'bxxxx;
		endcase
	end 

	always @(posedge Clock)
		if (Resetn  == 1'b0)	
			y_Q <= A;
		else
			y_Q <= Y_D;

	assign z = ((y_Q == E) | (y_Q == I)) ? 1'b1 : 1'b0;
	assign LEDR[3:0] = y_Q;
	assign LEDR[9] = z;
	assign LEDR[8:4] = 5'b0;
endmodule

